-- Storcătorul electric portabil pentru citrice este înlocuit cu blenderul portabil reîncărcabil USB (Helpship, stoc 0).
-- 1) Dacă storcătorul există (adăugat din admin), îl transformăm în blender, păstrând același produs (istoric comenzi neatins);
--    recenziile lui erau despre alt produs, așa că le ascundem (nu le ștergem).
UPDATE reviews SET approved = 0
WHERE product_id IN (SELECT id FROM products WHERE title LIKE '%torc%' AND title LIKE '%citric%');
UPDATE products SET slug = 'blender-portabil-reincarcabil-usb', title = 'Blender portabil reîncărcabil USB', subtitle = 'Smoothie-uri și sucuri proaspete oriunde, cu 4 lame din inox', description = 'Un blender mic, cât o sticlă, cu care îți faci smoothie-uri, shake-uri proteice și sucuri din fructe sau legume în câteva secunde. Pui ingredientele, apeși butonul și bei direct din recipient.

Are bateria încorporată de 1400 mAh, care se încarcă prin USB, așa că nu ai nevoie de priză când îl folosești: acasă, la birou, la sală sau pe drum.

Cele 4 lame din oțel inoxidabil mixează rapid fructele și legumele într-o băutură omogenă. Recipientul de 420 ml e din material fără BPA, sigur pentru alimente, iar mânerul din silicon îl face ușor de purtat. Se curăță simplu, cu puțină apă.',
  price = 7000, compare_at_price = 0, cost_price = 2000, sku = 'CHI-BLD-01', stock = 0, track_stock = 1, weight_g = 450,
  images = '["/img/blender-portabil-1.jpg", "/img/blender-portabil-2.jpg", "/img/blender-portabil-3.jpg", "/img/blender-portabil-4.jpg"]', benefits = '["Smoothie sau suc proaspăt în câteva secunde", "Fără fir: baterie de 1400 mAh, încărcare prin USB", "4 lame din oțel inoxidabil pentru o mixare uniformă", "Recipient de 420 ml fără BPA, cu mâner din silicon"]', faq = '[{"q": "Cum se încarcă?", "a": "Prin cablul USB, de la un încărcător de telefon, laptop sau baterie externă. Bateria încorporată are 1400 mAh, așa că nu ai nevoie de priză când îl folosești."}, {"q": "Ce pot prepara cu el?", "a": "Smoothie-uri, shake-uri proteice, sucuri din fructe și legume moi, piureuri. Pentru un rezultat bun, taie fructele în bucăți mici și adaugă lichid: apă, lapte sau suc."}, {"q": "Poate mixa gheață?", "a": "Poți adăuga câteva cuburi mici de gheață împreună cu lichid și fructe. Nu este gândit să pisezi doar gheață sau alimente foarte tari, cum ar fi nucile întregi."}, {"q": "Cât de mult încape?", "a": "Recipientul are o capacitate de 420 ml, adică o porție generoasă de smoothie, pe care o bei direct din el."}, {"q": "Cum se curăță?", "a": "Pui puțină apă în recipient, pornești blenderul câteva secunde, apoi clătești. Nu scufunda baza cu motorul în apă."}, {"q": "Cât durează livrarea?", "a": "24–48 de ore lucrătoare de la confirmarea comenzii. Plătești la livrare."}]', bundles = '[{"qty": 1, "pct": 0, "label": ""}, {"qty": 2, "pct": 10, "label": "Cel mai ales"}, {"qty": 3, "pct": 15, "label": "Cea mai bună ofertă"}]',
  badge = 'Nou', category = 'Bucătărie', active = 1,
  sections = '[{"title": "Smoothie proaspăt în câteva secunde", "image": "/img/blender-portabil-3.jpg", "text": "Pui fructele tăiate mărunt și puțin lichid, închizi capacul și apeși butonul. Cele 4 lame din oțel inoxidabil mixează totul într-o băutură fină în câteva secunde.\n\nBei direct din recipient, fără pahare și fără vase în plus de spălat."}, {"title": "Fără fir, fără priză", "image": "/img/blender-portabil-2.jpg", "text": "Bateria încorporată de 1400 mAh se încarcă prin USB, de la încărcătorul de telefon, de la laptop sau de la o baterie externă.\n\nÎl iei cu tine la birou, la sală, în parc sau în concediu și îți faci băutura acolo unde ești."}, {"title": "Pentru toată familia", "image": "/img/blender-portabil-4.jpg", "text": "Sucuri, smoothie-uri, shake-uri proteice după antrenament sau piureuri moi din fructe și legume. Un singur aparat mic, pentru mai multe rețete de zi cu zi.\n\nRecipientul e din material fără BPA, sigur pentru contactul cu alimentele."}, {"title": "Mic, ușor și simplu de curățat", "image": "/img/blender-portabil-1.jpg", "text": "Are dimensiunea unei sticle, iar mânerul din silicon îl face ușor de purtat în mână sau prins de rucsac.\n\nPentru curățare pui puțină apă, îl pornești câteva secunde și îl clătești. Gata pentru următoarea băutură."}]', specs = '[{"k": "Tip", "v": "Blender portabil, reîncărcabil"}, {"k": "Capacitate", "v": "420 ml"}, {"k": "Alimentare", "v": "Baterie încorporată, reîncărcabilă prin USB"}, {"k": "Baterie", "v": "1400 mAh"}, {"k": "Lame", "v": "4 lame din oțel inoxidabil"}, {"k": "Recipient", "v": "Material fără BPA, sigur pentru alimente"}, {"k": "Mâner", "v": "Silicon"}, {"k": "Potrivit pentru", "v": "Smoothie-uri, shake-uri proteice, sucuri din fructe și legume"}, {"k": "Unde îl folosești", "v": "Acasă, la birou, la sală, în călătorii"}]', fulfillment = 'helpship', length_cm = 25, width_cm = 10, height_cm = 10,
  updated_at = datetime('now')
WHERE id = (SELECT id FROM products WHERE title LIKE '%torc%' AND title LIKE '%citric%' ORDER BY id LIMIT 1)
  AND NOT EXISTS (SELECT 1 FROM products WHERE slug = 'blender-portabil-reincarcabil-usb');
-- 2) Dacă nu exista, îl adăugăm ca produs nou.
INSERT OR IGNORE INTO products (slug, title, price) VALUES ('blender-portabil-reincarcabil-usb', 'Blender portabil reîncărcabil USB', 7000);
